content.css:
.atlyn-network {
  --background: #fff;
  --foreground: #172d3d;
  --node: #007d87;
  --edge: #596579;
  --accent: #a64000;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  overflow: auto;
  color: var(--foreground);
  background: var(--background);
  font: 12px "Segoe UI", sans-serif;
  padding: 6px;
}
.atlyn-network * {
  box-sizing: border-box;
}
.atlyn-network [hidden] {
  display: none !important;
}
.atlyn-network button,
.atlyn-network input,
.atlyn-network select,
.atlyn-network summary {
  color: var(--foreground);
  background: var(--background);
  border: 1px solid var(--edge);
  border-radius: 4px;
  font: inherit;
  min-height: 30px;
  max-width: 100%;
  min-width: 0;
  padding: 5px 8px;
}
.atlyn-network button,
.atlyn-network summary {
  cursor: pointer;
}
.atlyn-network button {
  overflow-wrap: anywhere;
}
.atlyn-network button:hover,
.atlyn-network button[aria-pressed="true"] {
  border-color: var(--accent);
  outline: 1px solid var(--accent);
}
.atlyn-network button[aria-pressed="mixed"] {
  border: 2px dashed var(--accent);
}
.atlyn-network button:disabled {
  opacity: 0.5;
  cursor: default;
}
.atlyn-network button[aria-disabled="true"] {
  border-style: dashed;
}
.atlyn-network :focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}
.atlyn-network .network-header {
  display: flex;
  gap: 8px;
  align-items: start;
  flex: 0 0 auto;
  margin-bottom: 4px;
}
.atlyn-network .network-help {
  flex: 1;
  min-width: 0;
}
.atlyn-network .network-help > summary {
  font-weight: 650;
  font-size: 14px;
  border: none;
  padding-inline: 1px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.atlyn-network .network-help p {
  margin: 6px 0;
  line-height: 1.5;
}
.atlyn-network .network-licenses {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  max-height: 200px;
  overflow: auto;
  font: inherit;
}
.atlyn-network .network-tools {
  flex: 0 0 auto;
}
.atlyn-network .network-tools > summary {
  margin-bottom: 4px;
}
.atlyn-network:not(.compact) .network-tools > summary {
  display: none;
}
.atlyn-network .network-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  align-items: center;
  padding-bottom: 4px;
}
.atlyn-network .network-toolbar input {
  width: 175px;
}
.atlyn-network .network-toolbar select {
  max-width: min(205px, 100%);
}
.atlyn-network .network-status {
  padding: 5px 0;
  flex: 0 0 auto;
  max-height: 76px;
  overflow: auto;
  overflow-wrap: anywhere;
  line-height: 1.4;
}
.atlyn-network[data-incomplete="true"] .network-status {
  border-inline-start: 3px solid var(--accent);
  padding-inline-start: 6px;
}
.atlyn-network .network-notice {
  flex: 0 0 auto;
  max-height: 100px;
  overflow: auto;
  font-weight: 600;
  overflow-wrap: anywhere;
}
.atlyn-network .network-notice:not(:empty) {
  padding: 6px;
  border: 2px solid var(--accent);
}
.atlyn-network .network-body {
  display: flex;
  flex: 1 0 140px;
  min-height: 140px;
  min-width: 0;
  overflow: hidden;
  gap: 8px;
}
.atlyn-network .network-plot {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  min-height: 0;
  border: 1px solid var(--edge);
  border-radius: 4px;
  overflow: hidden;
}
.atlyn-network .network-svg {
  flex: 1 1 auto;
  min-width: 0;
  width: 100%;
  min-height: 80px;
  height: 100%;
  touch-action: none;
  user-select: none;
}
.atlyn-network .network-caption {
  flex: 0 0 36px;
  height: 36px;
  padding: 2px 5px;
  line-height: 16px;
  font-size: 11px;
  overflow: auto;
  border-top: 1px solid var(--edge);
}
.atlyn-network .network-list {
  flex: 0 0 34%;
  min-width: 230px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.atlyn-network .network-list-content {
  overflow: auto;
  flex: 1;
  min-height: 44px;
  scrollbar-gutter: stable;
}
.atlyn-network .network-list ul {
  list-style: none;
  padding: 0;
  margin: 0;
}
.atlyn-network .network-list li {
  border-bottom: 1px solid var(--edge);
  padding: 8px 3px;
  overflow-wrap: anywhere;
}
.atlyn-network .network-list li button {
  text-align: start;
}
.atlyn-network .network-list p {
  margin: 5px 0;
}
.atlyn-network .entity-counts {
  font-size: 11px;
}
.atlyn-network .list-actions,
.atlyn-network .network-tabs,
.atlyn-network .network-pager {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  align-items: center;
  flex: 0 0 auto;
}
.atlyn-network .list-actions {
  margin-top: 5px;
}
.atlyn-network .network-pager {
  padding-top: 5px;
}
.atlyn-network .network-node,
.atlyn-network .edge-hit {
  cursor: pointer;
}
.atlyn-network .network-node text {
  font-size: var(--label-size);
  unicode-bidi: plaintext;
  pointer-events: none;
  paint-order: stroke;
  stroke: var(--background);
  stroke-width: 3px;
  stroke-linejoin: round;
}
.atlyn-network .network-node.selected circle {
  stroke: var(--accent);
  stroke-width: 5px;
}
.atlyn-network .network-node[aria-pressed="mixed"] circle {
  stroke-dasharray: 5 2;
}
.atlyn-network .network-node.local-focus circle {
  stroke-dasharray: 3 2;
  stroke: var(--accent);
  stroke-width: 4px;
}
.atlyn-network .network-node.search-match circle {
  r: 18px;
  stroke: var(--accent);
  stroke-width: 4px;
}
.atlyn-network .network-edge.selected path:not(.edge-hit) {
  stroke: var(--accent);
  stroke-width: 4px;
}
.atlyn-network .network-node.dimmed circle {
  opacity: 0.4;
}
.atlyn-network .network-edge.dimmed path:not(.edge-hit) {
  opacity: 0.3;
}
.atlyn-network .network-list button.dimmed {
  border-style: dashed;
}
.atlyn-network.panning .network-svg,
.atlyn-network.panning .network-node,
.atlyn-network.panning .edge-hit {
  cursor: grabbing;
}
.atlyn-network.high-contrast .network-node.dimmed circle,
.atlyn-network.high-contrast .network-edge.dimmed path:not(.edge-hit) {
  opacity: 1;
  stroke-dasharray: 3 3;
}
.atlyn-network.high-contrast .network-node.dimmed circle {
  fill: var(--background);
  stroke: var(--foreground);
}
.atlyn-network.view-list .network-plot,
.atlyn-network.view-graph .network-list {
  display: none;
}
.atlyn-network.view-list .network-list {
  flex: 1;
  min-width: 0;
}
.atlyn-network.compact.view-split .network-body {
  flex-direction: column;
  flex-basis: 340px;
  min-height: 340px;
}
.atlyn-network.compact.view-split .network-plot {
  flex: 1;
  min-height: 140px;
}
.atlyn-network.compact.view-split .network-list {
  flex: 1;
  min-height: 140px;
  min-width: 0;
}
.atlyn-network.tiny {
  padding: 3px;
}
.atlyn-network.tiny .network-header {
  gap: 3px;
}
.atlyn-network.micro .network-header {
  flex-wrap: wrap;
}
.atlyn-network.micro .network-help {
  flex: 1 0 100%;
}
.atlyn-network.micro .network-pager > * {
  width: 100%;
}
@media (pointer: coarse) {
  .atlyn-network button,
  .atlyn-network input,
  .atlyn-network select,
  .atlyn-network summary {
    min-height: 44px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .atlyn-network *,
  .atlyn-network *::before,
  .atlyn-network *::after {
    animation: none !important;
    transition: none !important;
  }
}
